import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`photography-outreach`,heroTitle:`Turn your portfolio into paying clients`,heroSubtitle:`Perplexity Computer analyzes your design portfolio, crafts your creative positioning, and drafts personalized client outreach — automatically.`,inputUrlCta:`Analyze my portfolio`,inputUrlPlaceholder:`yourportfolio.com`,inputUrlPrefill:`Go to {url} and perform a deep analysis of my design/photography portfolio. 1) Study every project, image, and case study — identify recurring visual patterns, color palettes, composition styles, subject matter themes, and technical strengths. 2) Determine my unique creative positioning — what differentiates my work, what industries or aesthetics I'm strongest in, and what type of client would benefit most from my style. 3) Write a concise creative positioning statement and 3 key selling points I can use in outreach. 4) Research and identify 15 potential clients — brands, agencies, publications, or companies — whose visual identity or content needs align with my portfolio strengths. For each, include company name, why they're a match, and a relevant contact role to target. 5) Draft a personalized outreach email for each prospect that references their specific brand, explains why my work is relevant to them, and includes a clear call to action. Keep the tone professional but warm — not generic. Deliver everything in a structured document with sections for Portfolio Analysis, Creative Positioning, Target Client List, and Outreach Emails.`,heroOverlaySteps:[`Studying your portfolio for visual patterns, themes, and strengths`,`Crafting your creative positioning and unique selling points`,`Researching brands and clients that match your aesthetic`,`Personalized outreach emails drafted — ready to send`],generatingSteps:[`Visiting {url} to analyze your visual style, themes, and creative strengths`,`Designing an agent to match your portfolio to ideal clients and prospects`,`Configuring personalized outreach drafts for each target client`,`Setting up your positioning statement, prospect list, and email templates`],featureSectionTitle:`From portfolio to pipeline`,featureCardTitles:[`Connects to your creative stack`,`Outputs you can send today`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Gmail, Google Sheets, Notion, Google Drive, Slack — Computer sends outreach, tracks prospects, and organizes your pipeline in the tools you already use.`,`Portfolio analysis report. Creative positioning statement. 15 matched prospects with rationale. Personalized outreach emails ready to send.`],capabilitySectionTitle:`Your outreach team, on autopilot`,capabilitySectionSubtitle:`Paste your portfolio URL, step away, come back to a full client pipeline.`,capabilityCards:[{title:`Portfolio Analysis`,description:`Computer can study your entire body of work — visual patterns, color palettes, composition, subject matter — and surface the strengths clients care about.`},{title:`Creative Positioning`,description:`Computer can distill your portfolio into a clear positioning statement and selling points — so prospects instantly understand what makes your work different.`},{title:`Client Matching`,description:`Computer can research brands, agencies, and publications whose visual needs align with your style — and explain exactly why each one is a fit.`},{title:`Connect Your Tools`,description:`Computer can integrate with Gmail, Google Sheets, Notion, and Pipedrive — build workflows that send outreach and track responses across your stack.`},{title:`Remember & Refine`,description:`Computer can remember your positioning, past prospects, and response rates across sessions — so every outreach round gets sharper.`},{title:`Monitor & Alert`,description:`Computer can track prospect responses, flag new client opportunities that match your style, and alert you when it's time to follow up.`}]});export{t as default};
